def satisfies(version, spec):
    v = parse_version(version)
    for op in ["==", ">=", "<=", ">", "<"]:
        if spec.startswith(op):
            target = parse_version(spec[len(op):])
            break
    else:
        raise ValueError(f"Unknown spec: {spec}")
    if op == "==":
        return v == target
    if op == ">=":
        return v >= target
    if op == "<=":
        return v <= target
    if op == ">":
