        with open(name, encoding="utf-8") as f:
            days = {date.fromisoformat(line.strip()) for line in f if line.strip()}
    except FileNotFoundError:
        return []
    return sorted(days)

def mark_done(name, day):
    if day in load_days(name):
        return False
    with open(name, "a", encoding="utf-8") as f:
        f.write(day.isoformat() + "\n")
    return True

def current_streak(days, today):
    done = set(days)
    day = today if today in done else today - timedelta(days=1)
    streak = 0
    while day in done:
        streak += 1
        day -= timedelta(days=1)
    return streak

def longest_streak(days):
    best = 0
    run = 0
    previous = None
    for day in sorted(set(days)):
        if previous is not None and day - previous == timedelta(days=1):
            run += 1
        else:
            run = 1
        best = max(best, run)
        previous = day
    return best

def this_week(days, today):
    monday = today - timedelta(days=today.weekday())
    sunday = monday + timedelta(days=6)
    return sum(1 for day in set(days) if monday <= day <= sunday)

def days_text(n):
    return "1 day" if n == 1 else f"{n} days"


def summary(name, today):
    days = load_days(name)
    return [
        f"Done today: {'yes' if today in days else 'no'}",
        f"Current streak: {days_text(current_streak(days, today))}",
        f"Longest streak: {days_text(longest_streak(days))}",
        f"This week: {this_week(days, today)} of 7",
    ]


if __name__ == "__main__":
    for line in summary("habit.txt", date.today()):
        print(line)

