CODES = {"SAVE10": 10, "HALF": 50}


def apply_code(amount, code):
    percent = CODES.get(code.upper())
    if percent is None:
        raise ValueError(f"Unknown code: {code}")
    return round(amount * (100 - percent) / 100, 2)

