import shop


def main():
    cart = {}
    code = None
    while True:
        action, _, rest = input("> ").strip().partition(" ")
        if action == "done":
            break
        if action == "add" and rest:
            item, _, qty = rest.partition(" ")
            try:
                shop.add(cart, item, int(qty) if qty else 1)
                print(f"Added {item}")
            except ValueError as e:
                print(e)
        elif action == "code" and rest:
            try:
                shop.apply_code(0, rest)
                code = rest
                print(f"Code {rest.upper()} accepted")
            except ValueError as e:
                print(e)
        else:
            print("Commands: add <item> [qty], code <code>, done")
    for line in shop.receipt(cart):
        print(line)
    if code:
        print(f"With {code.upper()}: {shop.apply_code(shop.total(cart), code):.2f}")


if __name__ == "__main__":
    main()
